/**
 * The pieces behind the two Screen index pages (Prototypes › Tablet / Mobile › Screen index), and
 * the "area by area" cards Start Here › Overview reuses.
 *
 * Rows come from `screen-index-data.ts`, generated by `scripts/gen-screen-index.mjs` from the
 * running Storybook, so every count on these pages is computed, never typed. The nav groups come
 * from `src/pos/data/nav.ts`, so an area sits under the same heading here as in the app's own menu.
 */
import type { ReactNode } from 'react';
import { NAV_GROUPS } from '../../pos/data/nav';
import { DOC, DocLink, DocTable, Grid, HeroScreen, NavCard, Pill, ScreenCard, SubHead, art, mobilePrototype, screen, tabletPrototype } from '../docs-kit/docs-kit';
import type { LinkTarget } from '../docs-kit/docs-kit';
import { MOBILE_SCREENS, TABLET_SCREENS } from './screen-index-data';
import type { ScreenIndexRow } from './screen-index-data';

export type App = 'tablet' | 'mobile';

export const SCREENS: Record<App, ScreenIndexRow[]> = { tablet: TABLET_SCREENS, mobile: MOBILE_SCREENS };

/* ------------------------------------------------------------------ counts */

export interface AreaGroup {
  name: string;
  count: number;
  /** The area's first story, in sidebar order. */
  firstId: string;
  /** Its folders, in sidebar order. */
  topics: string[];
  rows: ScreenIndexRow[];
}

/** Areas in sidebar order (which is nav order), with their stories. */
export const areasOf = (rows: ScreenIndexRow[]): AreaGroup[] => {
  const out: AreaGroup[] = [];
  for (const r of rows) {
    let g = out.find((x) => x.name === r.area);
    if (!g) out.push((g = { name: r.area, count: 0, firstId: r.id, topics: [], rows: [] }));
    g.count++;
    g.rows.push(r);
    if (!g.topics.includes(r.topic)) g.topics.push(r.topic);
  }
  return out;
};

const plural = (n: number, one: string, many = `${one}s`) => `${n} ${n === 1 ? one : many}`;

/** "184 stories" for an app, or for one of its areas. */
export const countOf = (app: App, area?: string) => plural(area ? SCREENS[app].filter((r) => r.area === area).length : SCREENS[app].length, 'story', 'stories');

/** The bare count, for labels that put the noun elsewhere ("413 tablet stories"). */
export const storyCountOf = (app: App) => SCREENS[app].length;

/** "20 areas". */
export const areaCountOf = (app: App) => plural(areasOf(SCREENS[app]).length, 'area');

/** Total pill plus one pill per area with its count. */
export const AreaPills = ({ app }: { app: App }) => (
  <>
    <Pill tone="brand">{countOf(app)}</Pill>
    {areasOf(SCREENS[app]).map((g) => (
      <Pill key={g.name}>
        {g.name}
        <span style={{ color: DOC.muted, marginLeft: 6, fontWeight: 500 }}>{g.count}</span>
      </Pill>
    ))}
  </>
);

