export const AREA_COPY: Record<App, Record<string, AreaCopy>> = { tablet: TABLET_AREAS, mobile: MOBILE_AREAS };

/** Where an area opens in its prototype. */
export const areaHref = (app: App, area: AreaGroup): string | undefined => {
  const copy = AREA_COPY[app][area.name];
  if (app === 'tablet') return copy?.route ? tabletPrototype(copy.route) : undefined;
  return mobilePrototype(copy?.route ?? area.rows[0]?.route ?? '');
};

/* ------------------------------------------------------------------ groups */

export interface NavSection {
  heading: string;
  /** Art for the heading band. */
  art?: string;
  areas: string[];
}

/** The nav's own groups, headed as the app heads them, with getting around first. */
export const navSections = (): NavSection[] => [
  { heading: 'Getting around', areas: ['Global Nav', 'Sign-in'] },
  ...NAV_GROUPS.map((g) => ({
    heading: g.heading ?? 'Operations',
    art: g.heading === 'Pro Shop' ? art('banner-tee-sheet') : g.heading === 'Restaurant' ? art('banner-restaurant') : undefined,
    areas: g.items.map((i) => i.label),
  })),
];

/** One area as a card: its screen, its count, a line on what it is, and where to open it. */
const AreaCard = ({ app, area, n }: { app: App; area: AreaGroup; n: number }) => {
  const copy = AREA_COPY[app][area.name];
  const href = areaHref(app, area);
  const links: (LinkTarget & { label: ReactNode })[] = [];
  if (href) links.push({ label: 'Open in the prototype', href });
  links.push({ label: area.topics.length > 1 ? `Stories (${area.topics.length} topics)` : 'Stories', to: area.firstId });
  const eyebrow = `${n} · ${area.name} · ${plural(area.count, 'story', 'stories')}`;
  const title = copy?.title ?? area.name;
  const blurb = copy?.blurb ?? `${area.topics.join(', ')}.`;
  if (!copy?.shot) {
    return (
      <NavCard eyebrow={eyebrow} title={title} to={area.firstId} cta="Stories">
        {blurb}
      </NavCard>
    );
  }
  return (
    <ScreenCard src={screen(copy.shot)} frame={app === 'tablet' ? 'terminal' : 'handheld'} eyebrow={eyebrow} title={title} lookAt={copy.lookAt} links={links}>
      {blurb}
    </ScreenCard>
  );
};

/**
 * Every area of an app as cards, under the nav's group headings (Pro Shop, Restaurant, the rest),
 * numbered in nav order. Areas the app doesn't have yet are left out, so the phone shows only
 * what it has.
 */
export const AreaCards = ({ app, cols = 3 }: { app: App; cols?: 2 | 3 | 4 }) => {
  const areas = areasOf(SCREENS[app]);
  const number = new Map(areas.map((a, i) => [a.name, i + 1]));
  const placed = new Set<string>();
  const sections = navSections()
    .map((s) => ({ ...s, list: s.areas.map((name) => areas.find((a) => a.name === name)).filter((a): a is AreaGroup => !!a) }))
    .filter((s) => s.list.length > 0);
  sections.forEach((s) => s.list.forEach((a) => placed.add(a.name)));
  const rest = areas.filter((a) => !placed.has(a.name));
  return (
    <>
      {sections.map((s) => (
        <div key={s.heading}>
          <SubHead art={s.art}>{s.heading}</SubHead>
          <Grid cols={cols}>
            {s.list.map((a) => (
              <AreaCard key={a.name} app={app} area={a} n={number.get(a.name) ?? 0} />
            ))}
          </Grid>
        </div>
      ))}
      {rest.length > 0 && (
        <div>
          <SubHead>Other</SubHead>
          <Grid cols={cols}>
            {rest.map((a) => (
              <AreaCard key={a.name} app={app} area={a} n={number.get(a.name) ?? 0} />
            ))}
          </Grid>
        </div>
      )}
    </>
  );
};

/** The table: #, area and topic, the screen (name and one line), and where to open it. */
export const ScreenIndexTable = ({ app }: { app: App }) => (
  <DocTable
    columns={['#', 'Area', 'Screen', 'Open']}
    widths={[48, 200, 'auto', 130]}
    rows={SCREENS[app].map((r, i) => [
      <span key="n" style={{ color: DOC.muted, fontVariantNumeric: 'tabular-nums' }}>
        {i + 1}
      </span>,
      <span key="a" style={{ display: 'flex', flexDirection: 'column' }}>
        <span style={{ color: DOC.ink, fontWeight: 600 }}>{r.area}</span>
        {r.topic !== r.area && <span style={{ color: DOC.muted }}>{r.topic}</span>}
      </span>,
      <span key="s" style={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
        <strong style={{ color: DOC.ink, fontWeight: 600 }}>{r.name}</strong>
        <span>{r.description}</span>
      </span>,
      <span key="o" style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-start', gap: 2 }}>
        <DocLink to={r.id}>Story</DocLink>
        {r.route !== undefined && <DocLink href={mobilePrototype(r.route)}>Prototype</DocLink>}
      </span>,
    ])}
  />
);

